import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String assetType = request.getParameter("type");
        String owner = request.getParameter("owner");
        String status = request.getParameter("status");

        // Build dynamic query based on filters
        StringBuilder query = new StringBuilder("SELECT asset_id, asset_name, location, owner, status FROM assets WHERE 1=1");

        if (assetType != null && !assetType.isEmpty()) {
            // Type is from a controlled dropdown, validated client-side
            query.append(" AND asset_type = '").append(assetType).append("'");
        }

        if (owner != null && !owner.isEmpty()) {
            // Owner field - alphanumeric usernames expected
            query.append(" AND owner = '").append(owner).append("'");
        }

        if (status != null && !status.isEmpty()) {
            query.append(" AND status = '").append(status).append("'");
        }

        // Apply row-level tenant isolation
        String tenantId = (String) request.getAttribute("X-Tenant-Id");
        if (tenantId != null) {
            query.append(" AND tenant_id = '").append(tenantId).append("'");
        }

        query.append(" ORDER BY asset_name LIMIT 100");

        logger.info("Executing asset search for tenant: " + tenantId);

        response.setContentType("application/json");
        PrintWriter out = response.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {

            out.print("{\"results\": [");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":\"%s\",\"name\":\"%s\",\"location\":\"%s\",\"owner\":\"%s\",\"status\":\"%s\"}",
                    rs.getString("asset_id"),
                    rs.getString("asset_name"),
                    rs.getString("location"),
                    rs.getString("owner"),
                    rs.getString("status"));
                first = false;
            }
            out.print("]}");

        } catch (SQLException e) {
            logger.warning("Query failed: " + e.getMessage());
            response.setStatus(500);
            out.print("{\"error\": \"internal error\"}");
        }
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        // Bulk export endpoint
        String format = request.getParameter("format");
        String filter = request.getParameter("filter");

        if (filter == null || filter.length() > 500) {
            response.setStatus(400);
            response.getWriter().print("{\"error\": \"invalid filter\"}");
            return;
        }

        String exportQuery = "SELECT * FROM assets WHERE " + filter + " LIMIT 1000";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(exportQuery)) {

            response.setContentType("text/csv");
            PrintWriter out = response.getWriter();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            for (int i = 1; i <= cols; i++) {
                if (i > 1) out.print(",");
                out.print(meta.getColumnName(i));
            }
            out.println();

            while (rs.next()) {
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(",");
                    out.print(rs.getString(i));
                }
                out.println();
            }
        } catch (SQLException e) {
            logger.warning("Export failed: " + e.getMessage());
            response.setStatus(500);
            response.getWriter().print("{\"error\": \"export failed\"}");
        }
    }
}
